import { createHarness, type Harness } from './harness.js'

describe('reserved multi-agent commands', () => {
  let h: Harness

  beforeEach(() => {
    h = createHarness()
  })

  afterEach(() => {
    h.cleanup()
  })

  it.each(['install', 'activate', 'remove'])(
    'recognizes `%s` with a --agent option but reports it is not yet implemented',
    (command) => {
